import { IonButton, IonCard, IonCardContent, IonCardHeader, IonCardTitle, IonCol, IonContent, IonIcon, IonImg, IonItem, IonLabel, IonList, IonRadio, IonRadioGroup, IonRow, IonThumbnail, IonTitle, useIonViewWillEnter, } from '@ionic/react';
import { useHistory } from 'react-router';
import { useState } from 'react';
import { personAdd, radioButtonOff, radioButtonOn, refresh, save, server } from 'ionicons/icons';
import { useDispatch, useSelector } from 'react-redux';
import { loadingClientes, setClientes } from '../Store/Reducer/ReducerClientes';
import { setMainAmbiente } from '../Store/Reducer/ReducerAtividade';
import { RootState } from '../Store/ReduxStore';
import { ButtonLayoutProps, layoutGrupoBotoes } from '../components/ButtonLayout';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Navigation } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/navigation';

export interface ClienteInfoDTO {
    nome: string,
    imagem: string,
    ambientes: AmbienteInfoDTO[],
}

export interface AmbienteInfoDTO {
    nome: string,
    conexaoSftp: string,
    //usuarioSftp: string,
    //senhaSftp: string,
    conexaoBanco: string,
    //usuarioBanco: string,
    //senhaBanco: string,
}

const EscolherClientes: React.FC = () => {
    //Atrbiutos úteis
    const dispatch = useDispatch();
    const history = useHistory();
    const [conectionsCount, setConectionsCount] = useState<number>(0);
    const clientes = useSelector((state: RootState) => state.store.catalogoClientes.catalogo);
    const mainCliente = useSelector((state: RootState) => state.store.configAtividade.mainCliente);
    const mainAmbiente = useSelector((state: RootState) => state.store.configAtividade.mainAmbiente);

    //Atributos de botões
    const botaoAtualizar = {
        title: 'Atualizar',
        icon: refresh,
        trigger: () =>  coletarRecursos(),
        disable: false, //isLoading(),
    } as ButtonLayoutProps;

    const botaoNovoCliente = {
        title: 'Novo Cliente',
        icon: personAdd,
        trigger: () =>  null,
        disable: false, //isLoading(),
    } as ButtonLayoutProps;

    //Ações ao carregar esta página
    useIonViewWillEnter(() => {
        //dispatch(setButtons( [botaoAtualizar, botaoNovaPipeline] ));
        coletarRecursos();
    }, []);

    //Atualizando Pipelines e Jobs com base no banco
    async function coletarRecursos() {
        //dispatch(loadingClientes(true));
        //await obterClientesBanco();
        //dispatch(loadingClientes(false));
    }

    //Acionamento ao selecionar uma opção de Cliente
    function setClienteAmbiente(cliente: string, ambiente: string): void {
        console.log(`[ESCOLHER-CLIENTES]: Usuário selecionou Cliente: '${cliente}', Ambiente: '${ambiente}'.`);
        dispatch(setMainAmbiente({cliente, ambiente}));
    }

    const cardsDeClientes = () => clientes.map((cliente, indexCliente) =>
        <SwiperSlide key={indexCliente} className=''>
             <IonRow id="card-filme" className='ion-justify-content-center mb-4'>
                <IonCol size='12' sizeMd='6' id="filme-texto" className="glass m-2">
                    <IonThumbnail>
                        <IonImg id="filme-capa" alt="Logo do cliente" src={`data:image/png;base64,${cliente.imagem}`} className=''/>
                    </IonThumbnail> 
                </IonCol>
                <IonCol size='12' sizeMd='4' className='glass m-2'>
                    <IonContent className='ion-justify-content-center p-0 m-0'>
                        <IonTitle color='#' className='text-white m-0 py-3 text-center w-100'>
                            <span id="filme-title" className='h3 align-middle'>{cliente.nome}</span>
                        </IonTitle>
                        {/*setClienteAmbiente(cliente.nome, e.detail.value)*/}                
                        <IonList className='m-3 p-2 glass'>
                            {
                                cliente.ambientes.map((ambiente, indexAmbiente) => {
                                    const checked = mainCliente === cliente.nome 
                                        && mainAmbiente === ambiente.nome 
                                        ? radioButtonOn : radioButtonOff;
                                    return (
                                        <IonItem key={indexAmbiente} lines='none'
                                            color='#'
                                            className='p-0 m-0 align-items-center text-white w-100'
                                            style={{ '--min-height': '32px' }}
                                        >
                                            <IonIcon icon={checked} 
                                                color="primary" 
                                                size='large'
                                                className='btn border-0 p-0 pe-1' 
                                                style={{ transform: 'scale(1.2) translate(0.25px, 1.75px)' }}
                                                onClick={(e) => setClienteAmbiente(cliente.nome, ambiente.nome)}
                                            />
                                            <IonLabel className='px-1 py-2 m-0 rounded rounded-3'>
                                                <p className='lh-1 p-0 m-0 mx-1 mt-1 fw-bold text-white '>
                                                    Ambiente {ambiente.nome}
                                                </p>
                                                <p className='lh-1 p-0 m-0'>
                                                    <div className='text-white p-0 mx-1'>
                                                        <span>STP: </span> 
                                                        <span className='font-monospace'>{ambiente.conexaoSftp}</span>
                                                    </div>
                                                </p>
                                                <p className='lh-1 p-0 m-0'>
                                                    <div className='text-white p-0 mx-1'>
                                                        <span>BANCO: </span> 
                                                        <span className='font-monospace'>{ambiente.conexaoBanco}</span>
                                                    </div>
                                                </p>
                                            </IonLabel>
                                        </IonItem>
                                    );
                                })
                            }
                        </IonList>
                    </IonContent>
                </IonCol>
            </IonRow>
        </SwiperSlide>
    );

    return (
        <div className='container'>
            {layoutGrupoBotoes([ botaoAtualizar, botaoNovoCliente ])}
            <div className='ion-justify-content-center glass'>
                <div className='glass-content'>
                    <div className='p-0 m-0 my-1 text-white text-center '>
                        <span className='h5'>Lista de clientes disponíveis</span>
                    </div>
                    <Swiper navigation={true} modules={[Navigation]} >
                        {cardsDeClientes()}
                    </Swiper>
                </div>
            </div>
        </div>
    );

};

export default EscolherClientes;

